import React from "react";
import { render, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import Col from "../Col";
import * as stories from "./Row.stories";
import Row from "./Row";

const { Basic } = composeStories(stories) as any;

describe("Grid", () => {
  let consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(
      <Row data-testid="row">
        <Col data-testid="col">col</Col>
      </Row>
    );
    expect(screen.getByTestId("row")).toBeTruthy();
    expect(screen.getByTestId("col")).toBeTruthy();
  });

  it("allow xxs specific ordering", () => {
    render(
      <Row>
        <Col xxs={12} md={10}>
          first col
        </Col>
        <Col data-testid="col" xxs={12} md={2} order={{ xxs: "first", md: 0 }}>
          second col
        </Col>
      </Row>
    );
    expect(screen.queryByTestId("col")).toHaveClass("ds-order-first");
  });
});
